  'Search radius': { mr: 'शोध त्रिज्या', hi: 'खोज का दायरा' },
  'Refresh nearby': { mr: 'जवळचे पुन्हा शोधा', hi: 'आसपास फिर खोजें' },
  'Use my location': { mr: 'माझे स्थान वापरा', hi: 'मेरा स्थान उपयोग करें' },
